import sys

def contains_nearby_duplicate_brute(nums, k):
    n = len(nums)
    for i in range(n):
        for j in range(max(0, i - k), i):
            if nums[j] == nums[i]:
                return True
    return False

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    k = int(data[1 + n])
    print('true' if contains_nearby_duplicate_brute(nums, k) else 'false')

import sys

def contains_nearby_duplicate_opt(nums, k):
    last = {}
    for i, x in enumerate(nums):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
