    k = int(data[1 + n])
    print('true' if contains_nearby_duplicate_opt(nums, k) else 'false')

import sys
from collections import OrderedDict

def contains_nearby_duplicate_best(nums, k):
    window = OrderedDict()
    for i, x in enumerate(nums):
        if x in window:
            return True
        window[x] = i
        if len(window) > k:
            window.popitem(last=False)
    return False

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    k = int(data[1 + n])
    print('true' if contains_nearby_duplicate_best(nums, k) else 'false')
